1	//! A minimal L2 (market-by-price) order book.
2	//!
3	//! The book mirrors what an L2 feed publishes: one aggregate quantity per price
4	//! level per side. Updates are *absolute* ("level 50000.1 now holds 3.2"), not
5	//! deltas — sending qty 0 deletes the level. This is Binance-futures/Tardis
6	//! semantics and the dominant convention for crypto MBP feeds.
7	//!
8	//! Crossed/locked handling replicates hftbacktest's `HashMapMarketDepth`
9	//! (refs/hftbacktest/hftbacktest/src/depth/hashmapmarketdepth.rs:85-194): when an
10	//! update makes best_bid >= best_ask, the *opposite* best pointer skips past the
11	//! now-stale levels, but their map entries are retained — the feed is trusted to
12	//! refresh them. We must match this exactly for the P1.2 level-for-level
13	//! comparison against hftbacktest's reconstruction. We additionally count these
14	//! occurrences (`locked_updates` / `crossed_updates`), which hftbacktest doesn't.
15	
16	use std::collections::BTreeMap;
17	
18	/// Book side.
19	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
20	pub enum Side {
21	    Bid,
22	    Ask,
23	}
24	
25	/// One price level as (price, aggregate quantity).
26	#[derive(Clone, Copy, PartialEq, Debug)]
27	pub struct Level {
28	    pub px: f64,
29	    pub qty: f64,
30	}
31	
32	/// Top-of-book state derived from the current best pointers.
33	///
34	/// Because crossing updates resolve immediately (pointer skip), `Locked` and
35	/// `Crossed` can only be observed if resolution is bypassed; they are kept in
36	/// the enum because the P1.2 harness asserts the book is *never* in them after
37	/// an update. Transient locks/crosses show up in the counters instead.
38	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
39	pub enum BookState {
40	    Empty,
41	    BidOnly,
42	    AskOnly,
43	    Normal,
44	    Locked,
45	    Crossed,
46	}
47	
48	/// Minimal L2 order book over integer price ticks.
49	pub struct L2Book {
50	    tick_size: f64,
51	    lot_size: f64,
52	    bids: BTreeMap<i64, f64>,
53	    asks: BTreeMap<i64, f64>,
54	    best_bid: Option<i64>,
55	    best_ask: Option<i64>,
56	    /// Timestamp (ns) of the last applied update.
57	    pub last_ts: i64,
58	    /// Number of depth updates applied.
59	    pub depth_updates: u64,
60	    /// Updates that arrived locking the book (incoming level == opposite best).
61	    pub locked_updates: u64,
62	    /// Updates that arrived crossing the book (incoming level beyond opposite best).
63	    pub crossed_updates: u64,
64	}
65	
66	impl L2Book {
67	    pub fn new(tick_size: f64, lot_size: f64) -> Self {
68	        assert!(tick_size > 0.0 && lot_size > 0.0);
69	        Self {
70	            tick_size,
71	            lot_size,
72	            bids: BTreeMap::new(),
73	            asks: BTreeMap::new(),
74	            best_bid: None,
75	            best_ask: None,
76	            last_ts: 0,
77	            depth_updates: 0,
78	            locked_updates: 0,
79	            crossed_updates: 0,
80	        }
81	    }
82	
83	    /// Price -> integer tick. `round`, not `trunc`: f64 cannot represent most
84	    /// decimal prices exactly (50000.1 / 0.1 = 500000.99999...), so truncation
85	    /// would put the level one tick off.
86	    #[inline(always)]
87	    pub fn px_to_tick(&self, px: f64) -> i64 {
88	        (px / self.tick_size).round() as i64
89	    }
90	
91	    #[inline(always)]
92	    pub fn tick_to_px(&self, tick: i64) -> f64 {
93	        tick as f64 * self.tick_size
94	    }
95	
96	    /// Apply one incremental L2 update: set the aggregate quantity at a price
97	    /// level. `qty` rounding to zero lots deletes the level.
98	    pub fn set_level(&mut self, side: Side, px: f64, qty: f64, ts: i64) {
99	        let tick = self.px_to_tick(px);
100	        let qty_lots = (qty / self.lot_size).round() as i64;
101	        self.last_ts = ts;
102	        self.depth_updates += 1;
103	
104	        match side {
105	            Side::Bid => {
106	                if qty_lots == 0 {
107	                    self.bids.remove(&tick);
108	                    if self.best_bid == Some(tick) {
109	                        // Best bid deleted: next best is the highest remaining bid below.
110	                        self.best_bid = self.bids.range(..tick).next_back().map(|(&t, _)| t);
111	                    }
112	                } else {
113	                    self.bids.insert(tick, qty);
114	                    if self.best_bid.map_or(true, |b| tick > b) {
115	                        self.best_bid = Some(tick);
116	                        if let Some(a) = self.best_ask {
117	                            if tick >= a {
118	                                if tick == a {
119	                                    self.locked_updates += 1;
120	                                } else {
121	                                    self.crossed_updates += 1;
122	                                }
123	                                // Stale-ask skip: pointer moves strictly above the
124	                                // crossing bid; entries in (old ask ..= tick] remain
125	                                // until the feed refreshes them (hftbacktest:122-128).
126	                                self.best_ask =
127	                                    self.asks.range(tick + 1..).next().map(|(&t, _)| t);
128	                            }
129	                        }
130	                    }
131	                }
132	            }
133	            Side::Ask => {
134	                if qty_lots == 0 {
135	                    self.asks.remove(&tick);
136	                    if self.best_ask == Some(tick) {
137	                        self.best_ask = self.asks.range(tick + 1..).next().map(|(&t, _)| t);
138	                    }
139	                } else {
140	                    self.asks.insert(tick, qty);
141	                    if self.best_ask.map_or(true, |a| tick < a) {
142	                        self.best_ask = Some(tick);
143	                        if let Some(b) = self.best_bid {
144	                            if tick <= b {
145	                                if tick == b {
146	                                    self.locked_updates += 1;
147	                                } else {
148	                                    self.crossed_updates += 1;
149	                                }
150	                                // Mirror image: best bid drops strictly below the
151	                                // crossing ask (hftbacktest:177-183).
152	                                self.best_bid =
153	                                    self.bids.range(..tick).next_back().map(|(&t, _)| t);
154	                            }
155	                        }
156	                    }
157	                }
158	            }
159	        }
160	    }
161	
162	    /// Clear one side up to and including `upto_px` (toward the book interior),
163	    /// as emitted before a snapshot. `None` clears the whole side.
164	    ///
165	    /// Next-best search here is a clean range scan. hftbacktest's equivalent
166	    /// (hashmapmarketdepth.rs:208-209) scans from `clear_upto - 1` exclusive,
167	    /// skipping a possible level at exactly `clear_upto - 1`; harmless there
168	    /// because a full snapshot always follows a clear, but we don't copy it.
169	    pub fn clear_side(&mut self, side: Side, upto_px: Option<f64>) {
170	        match (side, upto_px) {
171	            (Side::Bid, None) => {
172	                self.bids.clear();
173	                self.best_bid = None;
174	            }
175	            (Side::Bid, Some(px)) => {
176	                let upto = self.px_to_tick(px);
177	                self.bids.retain(|&t, _| t < upto);
178	                self.best_bid = self.bids.range(..upto).next_back().map(|(&t, _)| t);
179	            }
180	            (Side::Ask, None) => {
181	                self.asks.clear();
182	                self.best_ask = None;
183	            }
184	            (Side::Ask, Some(px)) => {
185	                let upto = self.px_to_tick(px);
186	                self.asks.retain(|&t, _| t > upto);
187	                self.best_ask = self.asks.range(upto + 1..).next().map(|(&t, _)| t);
188	            }
189	        }
190	    }
191	
192	    pub fn clear_all(&mut self) {
193	        self.clear_side(Side::Bid, None);
194	        self.clear_side(Side::Ask, None);
195	    }
196	
197	    // ---- inspection ----
198	
199	    pub fn best_bid_tick(&self) -> Option<i64> {
200	        self.best_bid
201	    }
202	
203	    pub fn best_ask_tick(&self) -> Option<i64> {
204	        self.best_ask
205	    }
206	
207	    pub fn best_bid(&self) -> Option<Level> {
208	        self.best_bid.map(|t| Level {
209	            px: self.tick_to_px(t),
210	            qty: *self.bids.get(&t).unwrap_or(&0.0),
211	        })
212	    }
213	
214	    pub fn best_ask(&self) -> Option<Level> {
215	        self.best_ask.map(|t| Level {
216	            px: self.tick_to_px(t),
217	            qty: *self.asks.get(&t).unwrap_or(&0.0),
218	        })
219	    }
220	
221	    /// Mid price, defined only for a two-sided book.
222	    pub fn mid(&self) -> Option<f64> {
223	        match (self.best_bid, self.best_ask) {
224	            (Some(b), Some(a)) => Some((self.tick_to_px(b) + self.tick_to_px(a)) / 2.0),
225	            _ => None,
226	        }
227	    }
228	
229	    /// Spread in ticks (>= 1 whenever the book is two-sided, by construction).
230	    pub fn spread_ticks(&self) -> Option<i64> {
231	        match (self.best_bid, self.best_ask) {
232	            (Some(b), Some(a)) => Some(a - b),
233	            _ => None,
234	        }
235	    }
236	
237	    pub fn state(&self) -> BookState {
238	        match (self.best_bid, self.best_ask) {
239	            (None, None) => BookState::Empty,
240	            (Some(_), None) => BookState::BidOnly,
241	            (None, Some(_)) => BookState::AskOnly,
242	            (Some(b), Some(a)) if b > a => BookState::Crossed,
243	            (Some(b), Some(a)) if b == a => BookState::Locked,
244	            _ => BookState::Normal,
245	        }
246	    }
247	
248	    /// Aggregate quantity at a tick (0 if absent). Reads the raw map, so stale
249	    /// retained levels are visible here — intentionally, for parity checks.
250	    pub fn qty_at_tick(&self, side: Side, tick: i64) -> f64 {
251	        let map = match side {
252	            Side::Bid => &self.bids,
253	            Side::Ask => &self.asks,
254	        };
255	        *map.get(&tick).unwrap_or(&0.0)
256	    }
257	
258	    /// Top `n` levels from the best pointer toward the interior. Stale entries
259	    /// beyond the pointer (crossing leftovers) are excluded — this is "the book
260	    /// as the venue would display it".
261	    pub fn top_n(&self, side: Side, n: usize) -> Vec<Level> {
262	        match side {
263	            Side::Bid => match self.best_bid {
264	                None => Vec::new(),
265	                Some(b) => self
266	                    .bids
267	                    .range(..=b)
268	                    .rev()
269	                    .take(n)
270	                    .map(|(&t, &q)| Level { px: self.tick_to_px(t), qty: q })
271	                    .collect(),
272	            },
273	            Side::Ask => match self.best_ask {
274	                None => Vec::new(),
275	                Some(a) => self
276	                    .asks
277	                    .range(a..)
278	                    .take(n)
279	                    .map(|(&t, &q)| Level { px: self.tick_to_px(t), qty: q })
280	                    .collect(),
281	            },
282	        }
283	    }
284	
285	    /// Number of price levels currently stored (including stale retained ones).
286	    pub fn n_levels(&self, side: Side) -> usize {
287	        match side {
288	            Side::Bid => self.bids.len(),
289	            Side::Ask => self.asks.len(),
290	        }
291	    }
292	}
293	
294	#[cfg(test)]
295	mod tests {
296	    use super::*;
297	
298	    fn book() -> L2Book {
299	        // BTCUSDT-perp-like: tick 0.1, lot 0.001
300	        L2Book::new(0.1, 0.001)
301	    }
302	
303	    /// Display prices are reconstructed as `tick * tick_size`, an inexact f64
304	    /// product (500000 * 0.1 != 50000.0 exactly) — the very reason the book
305	    /// keys on integer ticks. Tests therefore assert ticks with `==` and
306	    /// display prices only approximately.
307	    fn assert_px(actual: f64, expected: f64) {
308	        assert!(
309	            (actual - expected).abs() < 1e-6,
310	            "px {actual} != {expected}"
311	        );
312	    }
313	
314	    #[test]
315	    fn empty_book() {
316	        let b = book();
317	        assert_eq!(b.state(), BookState::Empty);
318	        assert_eq!(b.best_bid(), None);
319	        assert_eq!(b.best_ask(), None);
320	        assert_eq!(b.mid(), None);
321	        assert!(b.top_n(Side::Bid, 5).is_empty());
322	    }
323	
324	    #[test]
325	    fn tick_rounding_is_exact_for_decimal_prices() {
326	        let b = book();
327	        // 50000.1 / 0.1 = 500000.99999... in f64; round() must land on 500001.
328	        assert_eq!(b.px_to_tick(50_000.1), 500_001);
329	        assert_eq!(b.px_to_tick(50_000.0), 500_000);
330	        assert_eq!(b.px_to_tick(0.1), 1);
331	    }
332	
333	    #[test]
334	    fn basic_two_sided_book() {
335	        let mut b = book();
336	        b.set_level(Side::Bid, 50_000.0, 1.0, 1);
337	        b.set_level(Side::Bid, 49_999.9, 2.0, 2);
338	        b.set_level(Side::Ask, 50_000.2, 1.5, 3);
339	        b.set_level(Side::Ask, 50_000.3, 3.0, 4);
340	
341	        assert_eq!(b.state(), BookState::Normal);
342	        assert_eq!(b.best_bid_tick(), Some(500_000));
343	        assert_eq!(b.best_ask_tick(), Some(500_002));
344	        assert_px(b.best_bid().unwrap().px, 50_000.0);
345	        assert_px(b.best_ask().unwrap().px, 50_000.2);
346	        assert_eq!(b.spread_ticks(), Some(2));
347	        assert_px(b.mid().unwrap(), 50_000.1);
348	    }
349	
350	    #[test]
351	    fn updates_are_absolute_not_deltas() {
352	        let mut b = book();
353	        b.set_level(Side::Bid, 50_000.0, 1.0, 1);
354	        b.set_level(Side::Bid, 50_000.0, 2.5, 2);
355	        assert_eq!(b.best_bid().unwrap().qty, 2.5); // replaced, not 3.5
356	    }
357	
358	    #[test]
359	    fn zero_qty_deletes_and_promotes_next_best() {
360	        let mut b = book();
361	        b.set_level(Side::Bid, 50_000.0, 1.0, 1);
362	        b.set_level(Side::Bid, 49_999.8, 2.0, 2);
363	        b.set_level(Side::Bid, 50_000.0, 0.0, 3);
364	        assert_eq!(b.best_bid_tick(), Some(499_998));
365	
366	        // Deleting a non-best level must not move the best pointer.
367	        b.set_level(Side::Bid, 49_999.0, 5.0, 4);
368	        b.set_level(Side::Bid, 49_999.0, 0.0, 5);
369	        assert_eq!(b.best_bid_tick(), Some(499_998));
370	
371	        // Sub-lot dust (< lot_size/2) rounds to zero lots -> also a delete.
372	        b.set_level(Side::Bid, 49_999.8, 0.0004, 6);
373	        assert_eq!(b.best_bid(), None);
374	        assert_eq!(b.state(), BookState::Empty);
375	    }
376	
377	    #[test]
378	    fn crossing_bid_skips_pointer_but_retains_stale_asks() {
379	        let mut b = book();
380	        b.set_level(Side::Bid, 50_000.0, 1.0, 1);
381	        b.set_level(Side::Ask, 50_000.2, 1.0, 2);
382	        b.set_level(Side::Ask, 50_000.5, 2.0, 3);
383	
384	        // Bid jumps over the best ask.
385	        b.set_level(Side::Bid, 50_000.3, 0.7, 4);
386	
387	        assert_eq!(b.crossed_updates, 1);
388	        assert_eq!(b.state(), BookState::Normal); // resolved immediately
389	        assert_eq!(b.best_bid_tick(), Some(500_003));
390	        assert_eq!(b.best_ask_tick(), Some(500_005)); // skipped past 50000.2
391	
392	        // hftbacktest parity: the stale ask entry is retained in the map...
393	        assert_eq!(b.qty_at_tick(Side::Ask, b.px_to_tick(50_000.2)), 1.0);
394	        // ...but excluded from the displayed ladder.
395	        let asks = b.top_n(Side::Ask, 5);
396	        assert_px(asks[0].px, 50_000.5);
397	        assert_eq!(asks.len(), 1);
398	    }
399	
400	    #[test]
401	    fn locking_update_is_counted_and_resolved() {
402	        let mut b = book();
403	        b.set_level(Side::Bid, 50_000.0, 1.0, 1);
404	        b.set_level(Side::Ask, 50_000.2, 1.0, 2);
405	        // Ask lands exactly on the best bid -> locked, bid pointer must drop.
406	        b.set_level(Side::Ask, 50_000.0, 1.0, 3);
407	        assert_eq!(b.locked_updates, 1);
408	        assert_eq!(b.best_ask_tick(), Some(500_000));
409	        assert_eq!(b.best_bid(), None); // no bid left below
410	        assert_eq!(b.state(), BookState::AskOnly);
411	    }
412	
413	    #[test]
414	    fn crossing_ask_drops_bid_below_crossing_price() {
415	        let mut b = book();
416	        b.set_level(Side::Bid, 50_000.0, 1.0, 1);
417	        b.set_level(Side::Bid, 49_999.9, 1.0, 2);
418	        b.set_level(Side::Bid, 49_999.5, 1.0, 3);
419	        b.set_level(Side::Ask, 50_000.5, 1.0, 4);
420	
421	        // Ask crosses deep: below best AND second-best bid.
422	        b.set_level(Side::Ask, 49_999.8, 0.4, 5);
423	
424	        assert_eq!(b.crossed_updates, 1);
425	        // New best bid is the highest bid strictly below the crossing ask,
426	        // not strictly below the old best bid (hftbacktest:179-182 parity).
427	        assert_eq!(b.best_bid_tick(), Some(499_995));
428	        assert_eq!(b.best_ask_tick(), Some(499_998));
429	        // Stale bids retained in the map, hidden from the ladder.
430	        assert_eq!(b.qty_at_tick(Side::Bid, b.px_to_tick(50_000.0)), 1.0);
431	        assert_px(b.top_n(Side::Bid, 5)[0].px, 49_999.5);
432	    }
433	
434	    #[test]
435	    fn top_n_orders_outward_from_best() {
436	        let mut b = book();
437	        for (i, px) in [50_000.0, 49_999.9, 49_999.7, 49_999.6].iter().enumerate() {
438	            b.set_level(Side::Bid, *px, (i + 1) as f64, i as i64);
439	        }
440	        let bids = b.top_n(Side::Bid, 3);
441	        let ticks: Vec<i64> = bids.iter().map(|l| b.px_to_tick(l.px)).collect();
442	        assert_eq!(ticks, vec![500_000, 499_999, 499_997]); // descending, truncated
443	    }
444	
445	    #[test]
446	    fn clear_full_and_upto() {
447	        let mut b = book();
448	        b.set_level(Side::Bid, 50_000.0, 1.0, 1);
449	        b.set_level(Side::Bid, 49_999.9, 1.0, 2);
450	        b.set_level(Side::Bid, 49_999.8, 1.0, 3);
451	        b.set_level(Side::Ask, 50_000.2, 1.0, 4);
452	
453	        // Clear bids down to and including 49999.9.
454	        b.clear_side(Side::Bid, Some(49_999.9));
455	        assert_eq!(b.best_bid_tick(), Some(499_998));
456	        assert_eq!(b.n_levels(Side::Bid), 1);
457	
458	        b.clear_all();
459	        assert_eq!(b.state(), BookState::Empty);
460	        assert_eq!(b.n_levels(Side::Ask), 0);
461	    }
462	
463	    #[test]
464	    fn snapshot_rebuild_after_clear() {
465	        let mut b = book();
466	        b.set_level(Side::Bid, 50_000.0, 1.0, 1);
467	        b.set_level(Side::Ask, 50_000.2, 1.0, 2);
468	        // Day-boundary pattern in our npz: clear then snapshot rows as plain sets.
469	        b.clear_all();
470	        b.set_level(Side::Bid, 51_000.0, 2.0, 3);
471	        b.set_level(Side::Ask, 51_000.4, 2.0, 4);
472	        assert_eq!(b.best_bid_tick(), Some(510_000));
473	        assert_eq!(b.best_ask_tick(), Some(510_004));
474	        assert_eq!(b.spread_ticks(), Some(4));
475	    }
476	
477	    /// Pseudo-random soak: after every update the book must be uncrossed and the
478	    /// best pointers must sit on live levels. Catches pointer-maintenance bugs
479	    /// that handpicked cases miss.
480	    #[test]
481	    fn invariants_hold_under_random_updates() {
482	        let mut b = book();
483	        let mut state: u64 = 0x9E37_79B9_7F4A_7C15;
484	        let mut rng = move || {
485	            // xorshift64* — tiny deterministic PRNG, no dependencies
486	            state ^= state >> 12;
487	            state ^= state << 25;
488	            state ^= state >> 27;
489	            state = state.wrapping_mul(0x2545_F491_4F6C_DD1D);
490	            state
491	        };
492	        for i in 0..100_000 {
493	            let r = rng();
494	            let side = if r & 1 == 0 { Side::Bid } else { Side::Ask };
495	            let tick = 500_000 + ((r >> 8) % 41) as i64 - 20; // ±20 ticks around 50k
496	            let qty = if (r >> 16) % 4 == 0 { 0.0 } else { ((r >> 24) % 100) as f64 * 0.001 };
497	            b.set_level(side, tick as f64 * 0.1, qty, i);
498	
499	            if let (Some(bb), Some(ba)) = (b.best_bid_tick(), b.best_ask_tick()) {
500	                assert!(bb < ba, "book crossed/locked after update {i}: bid {bb} ask {ba}");
501	            }
502	            if let Some(bb) = b.best_bid_tick() {
503	                assert!(b.qty_at_tick(Side::Bid, bb) > 0.0, "best bid points at empty level");
504	            }
505	            if let Some(ba) = b.best_ask_tick() {
506	                assert!(b.qty_at_tick(Side::Ask, ba) > 0.0, "best ask points at empty level");
507	            }
508	        }
509	        // The soak must actually have exercised the interesting paths.
510	        assert!(b.crossed_updates + b.locked_updates > 0);
511	    }
512	}
