1	//! Streaming reader for hftbacktest `.npz` event files.
2	//!
3	//! An `.npz` is a zip archive whose members are `.npy` arrays; ours holds a
4	//! single member `data.npy`: a 26M-row structured array of 64-byte `Event`
5	//! records, deflate-compressed (~197 MB on disk, ~1.7 GB raw). hftbacktest's
6	//! reader decompresses the whole array into memory; on an 8 GB machine we
7	//! stream instead — constant memory, one pass, records decoded on the fly.
8	//!
9	//! Container parsing is done by hand (it's ~80 lines and worth knowing):
10	//! - zip: the End Of Central Directory record (trailer) locates the central
11	//!   directory, which locates the member's local header and sizes. We read the
12	//!   trailer rather than trusting the local header because zip writers may
13	//!   leave local-header sizes zeroed (data-descriptor mode).
14	//! - npy: magic + version + a Python-dict header giving dtype and shape.
15	//!   We require the exact dtype our `Event` struct mirrors and fail loudly
16	//!   otherwise — silent layout drift would corrupt every downstream number.
17	//!
18	//! Format references: PKWARE APPNOTE (zip), numpy NEP "npy format" (npy),
19	//! refs/hftbacktest/hftbacktest/src/backtest/data/ (their reader, for parity).
20	
21	use std::fs::File;
22	use std::io::{self, BufReader, Read, Seek, SeekFrom};
23	use std::path::Path;
24	
25	use flate2::bufread::DeflateDecoder;
26	
27	use crate::events::Event;
28	
29	/// The exact structured dtype written by hftbacktest's converters.
30	/// Field order and widths must mirror `Event` — checked at open time.
31	const EXPECTED_DESCR: &str = "[('ev', '<u8'), ('exch_ts', '<i8'), ('local_ts', '<i8'), \
32	('px', '<f8'), ('qty', '<f8'), ('order_id', '<u8'), ('ival', '<i8'), ('fval', '<f8')]";
33	
34	const EVENT_SIZE: usize = 64;
35	
