1	//! P2.3 latency model: calibrated from feed timestamps.
2	//!
3	//! The feed latency (local_ts - exch_ts) is a lower bound on order round-trip
4	//! latency, because it only measures the data-path delay — not the order-path.
5	//! On co-located infrastructure the two are roughly equal; on retail infra the
6	//! order-path is typically 1–3× the feed delay. We calibrate from feed data
7	//! and expose the multiplier as a parameter.
8	//!
9	//! **Race-mode model** (arXiv 2603.24137): when a significant trigger event
10	//! (large trade, best-quote change) occurs, many participants react within one
11	//! exchange round-trip. The exchange queues all concurrent orders by arrival
12	//! time; effectively your order competes against a burst of orders clustered
13	//! within `race_window_ns` of the trigger. `RaceAwareLatency` adds a uniform
14	//! jitter in [0, race_window_ns] to the base latency around trigger events.
15	
16	/// Provides order entry and response latencies (nanoseconds).
17	pub trait LatencyModel {
18	    /// Returns the entry latency (req → exchange) for an order sent at `now`.
19	    fn entry_ns(&mut self, now: i64) -> i64;
20	    /// Returns the response latency (exchange → local) for an order matched at `now`.
21	    fn response_ns(&mut self, now: i64) -> i64;
22	    /// Notify the model that a trigger event occurred at `now` (large trade /
23	    /// best-quote change). Race-aware models activate a race window.
24	    fn on_trigger(&mut self, _now: i64) {}
25	}
26	
27	// ── xorshift64* ─────────────────────────────────────────────────────────────
28	// Deterministic PRNG for sampling inside the latency model (no external deps).
29	struct Xor64 {
30	    state: u64,
31	}
32	
33	impl Xor64 {
34	    fn new(seed: u64) -> Self {
35	        Self { state: seed | 1 }
36	    }
37	
38	    fn next(&mut self) -> u64 {
39	        let mut x = self.state;
40	        x ^= x << 13;
41	        x ^= x >> 7;
42	        x ^= x << 17;
43	        self.state = x;
44	        x.wrapping_mul(0x2545F4914F6CDD1D)
45	    }
46	
47	    /// Uniform sample in [0, n).
48	    fn next_u64_mod(&mut self, n: u64) -> u64 {
49	        if n == 0 { return 0; }
50	        self.next() % n
51	    }
52	
53	    /// Uniform f64 in [0, 1).
54	    fn next_f64(&mut self) -> f64 {
55	        (self.next() >> 11) as f64 * (1.0 / (1u64 << 53) as f64)
56	    }
57	}
58	
59	// ── Ziggurat-free log-normal sampler ─────────────────────────────────────────
60	// Box-Muller: two uniform samples → one standard normal → exponentiate.
61	// Sufficient for the ~10 samples per backtest step we need.
62	fn log_normal_sample(rng: &mut Xor64, mu: f64, sigma: f64) -> f64 {
63	    let u1 = rng.next_f64().max(1e-15);
64	    let u2 = rng.next_f64();
65	    let z = (-2.0 * u1.ln()).sqrt() * (2.0 * std::f64::consts::PI * u2).cos();
66	    (mu + sigma * z).exp()
67	}
68	
69	// ── ConstantLatency ───────────────────────────────────────────────────────────
70	
71	/// Deterministic constant latency — the naive baseline (hftbacktest default).
72	pub struct ConstantLatency {
73	    entry: i64,
74	    response: i64,
75	}
76	
77	impl ConstantLatency {
78	    pub fn new(entry_ns: i64, response_ns: i64) -> Self {
79	        Self { entry: entry_ns, response: response_ns }
80	    }
81	}
82	
83	impl LatencyModel for ConstantLatency {
84	    fn entry_ns(&mut self, _now: i64) -> i64 { self.entry }
85	    fn response_ns(&mut self, _now: i64) -> i64 { self.response }
86	}
87	
88	// ── LogNormalLatency ──────────────────────────────────────────────────────────
89	
90	/// Samples entry and response latency from a log-normal distribution
91	/// calibrated from feed data. The `roundtrip_multiplier` scales feed latency
92	/// to estimated order round-trip (default 2.0: entry ≈ response ≈ feed delay).
93	pub struct LogNormalLatency {
94	    /// ln(µs) location parameter of the log-normal.
95	    mu: f64,
96	    /// Shape parameter (scale of the log distribution).
97	    sigma: f64,
98	    /// Multiply the feed-latency sample by this to get entry latency.
99	    entry_mult: f64,
100	    /// Multiply the feed-latency sample by this to get response latency.
101	    response_mult: f64,
102	    rng: Xor64,
103	}
104	
105	impl LogNormalLatency {
106	    /// Construct from calibrated feed-latency log-normal params.
107	    /// `mu_log_us` / `sigma` are in log(µs); `roundtrip_mult` is typically 1.0
108	    /// (entry leg only; the return path is separate via `response_mult`).
109	    pub fn new(mu_log_us: f64, sigma: f64, entry_mult: f64, response_mult: f64, seed: u64) -> Self {
110	        Self { mu: mu_log_us, sigma, entry_mult, response_mult, rng: Xor64::new(seed) }
111	    }
112	
113	    fn sample_us(&mut self) -> f64 {
114	        log_normal_sample(&mut self.rng, self.mu, self.sigma).max(0.0)
115	    }
116	}
117	
118	impl LatencyModel for LogNormalLatency {
119	    fn entry_ns(&mut self, _now: i64) -> i64 {
120	        (self.sample_us() * self.entry_mult * 1000.0).round() as i64
121	    }
122	
123	    fn response_ns(&mut self, _now: i64) -> i64 {
124	        (self.sample_us() * self.response_mult * 1000.0).round() as i64
125	    }
126	}
127	
128	// ── RaceAwareLatency ─────────────────────────────────────────────────────────
129	
130	/// Log-normal base latency + race-mode jitter around trigger events.
131	///
132	/// After `on_trigger(T)`, for the next `race_window_ns` nanoseconds every
133	/// `entry_ns()` call adds a uniform jitter U(0, race_jitter_ns) to simulate
134	/// competing against other participants who all reacted to the same event at
135	/// approximately the same time. The race window should be set to the estimated
136	/// exchange round-trip latency (≈ mode × 2 of the feed latency distribution).
137	pub struct RaceAwareLatency {
138	    base: LogNormalLatency,
139	    race_jitter_ns: i64,
140	    race_window_ns: i64,
141	    race_active_until: i64,
142	}
143	
144	impl RaceAwareLatency {
145	    pub fn new(
146	        mu_log_us: f64,
147	        sigma: f64,
148	        entry_mult: f64,
149	        response_mult: f64,
