1	//! P2.4 market-impact propagator: Bouchaud power-law kernel.
2	//!
3	//! After each simulated fill, the caller registers a signed volume impulse.
4	//! The propagator sums decaying contributions from all past impulses to
5	//! compute the current price shift (in ticks). This shifts the mid-price
6	//! seen by subsequent strategy logic — the "market reacts to us" feedback
7	//! that naive replay ignores.
8	//!
9	//! **Model:** G(τ) = G₀ × τ^{-β} (power-law decay, τ in seconds).
10	//! Impact from impulse at time T: G(now - T) × sign × κ × sqrt(volume).
11	//! Accumulated: impact(now) = Σ_k G(now - t_k) × ε_k × κ × √V_k.
12	//!
13	//! **Calibrated parameters (BTCUSDT-perp 2026-05-01):**
14	//! - G₀ = 64.76 ticks (1-second impact per unit-normalised volume)
15	//! - β  = 0.50 (Bouchaud literature prior — single trending day can't identify β)
16	//! - κ  = 162.6 ticks/√BTC (square-root law amplitude from 100ms response)
17	//! - Cutoff: impulses older than 60 s are dropped (negligible contribution).
18	//!
19	//! **Usage:**
20	//! ```rust,ignore
21	//! let mut kernel = PropagatorKernel::calibrated(); // default BTCUSDT params
22	//! kernel.push(now_ns, 1.0, 0.5);   // buy fill: sign=+1, 0.5 BTC
23	//! let shift = kernel.impact(now_ns); // ticks to add to mid
24	//! ```
25	
26	/// One registered impulse: (timestamp ns, signed volume contribution).
27	struct Impulse {
28	    ts_ns: i64,
29	    signed_sqrt_vol: f64, // ε × √V  (√BTC)
30	}
31	
32	/// Bouchaud power-law propagator kernel.
33	pub struct PropagatorKernel {
34	    g0: f64,      // amplitude at τ=1s (ticks per unit √V, after κ normalisation)
35	    beta: f64,    // decay exponent
36	    kappa: f64,   // sqrt-law amplitude (ticks / √BTC)
37	    cutoff_ns: i64, // drop impulses older than this
38	    impulses: Vec<Impulse>,
39	}
40	
41	impl PropagatorKernel {
42	    pub fn new(g0_ticks: f64, beta: f64, kappa_ticks_per_sqrt_btc: f64, cutoff_s: f64) -> Self {
43	        Self {
44	            g0: g0_ticks,
45	            beta,
46	            kappa: kappa_ticks_per_sqrt_btc,
47	            cutoff_ns: (cutoff_s * 1e9) as i64,
48	            impulses: Vec::new(),
49	        }
50	    }
51	
52	    /// Construct from BTCUSDT-perp 2026-05-01 calibrated parameters.
53	    pub fn calibrated() -> Self {
54	        Self::new(64.76, 0.5, 162.57, 60.0)
55	    }
56	
57	    /// Register a fill: `sign` = +1 (buy) / -1 (sell), `volume_btc` ≥ 0.
58	    pub fn push(&mut self, ts_ns: i64, sign: f64, volume_btc: f64) {
59	        if volume_btc <= 0.0 { return; }
60	        let signed_sqrt_vol = sign * volume_btc.sqrt();
61	        self.impulses.push(Impulse { ts_ns, signed_sqrt_vol });
62	    }
63	
64	    /// Compute accumulated price impact at `now_ns` (ticks). Positive = mid shifted up.
65	    /// Also prunes expired impulses (age > cutoff).
66	    pub fn impact(&mut self, now_ns: i64) -> f64 {
67	        let cutoff_ts = now_ns - self.cutoff_ns;
68	        self.impulses.retain(|imp| imp.ts_ns >= cutoff_ts);
69	
70	        let mut acc = 0.0_f64;
71	        let ns_per_s = 1e9_f64;
72	        for imp in &self.impulses {
73	            let tau_s = (now_ns - imp.ts_ns) as f64 / ns_per_s;
74	            if tau_s <= 0.0 { continue; }
75	            // G(τ) = G₀ × τ^{-β}; normalise so G(1s)=G₀.
76	            let g = self.g0 * tau_s.powf(-self.beta);
77	            acc += g * imp.signed_sqrt_vol;
78	        }
79	        // Multiply by κ to convert from normalised √BTC space to ticks.
80	        acc * self.kappa / self.g0
81	        // Division by g0 because: impact(τ=1s, V=1) = g0 × 1^{-β} × κ × √1 / g0 = κ
82	        // i.e., the 1-second impact of a 1-BTC fill = κ ticks.
83	    }
84	
85	    /// Return the number of active impulses in the kernel.
86	    pub fn len(&self) -> usize {
87	        self.impulses.len()
88	    }
89	
90	    pub fn is_empty(&self) -> bool {
91	        self.impulses.is_empty()
92	    }
93	}
94	
95	#[cfg(test)]
96	mod tests {
97	    use super::*;
98	
99	    #[test]
100	    fn single_buy_gives_positive_impact() {
101	        let mut k = PropagatorKernel::calibrated();
102	        k.push(0, 1.0, 1.0); // buy 1 BTC at t=0
103	        // At τ=1s: impact = κ ticks ≈ 162 ticks
104	        let imp = k.impact(1_000_000_000); // 1s later
105	        assert!(imp > 0.0, "buy should produce positive impact, got {imp}");
106	        assert!(imp > 100.0 && imp < 300.0, "1s/1BTC impact should be ~163 ticks, got {imp}");
107	    }
108	
109	    #[test]
110	    fn sell_gives_negative_impact() {
111	        let mut k = PropagatorKernel::calibrated();
112	        k.push(0, -1.0, 1.0); // sell 1 BTC
113	        let imp = k.impact(1_000_000_000);
114	        assert!(imp < 0.0, "sell should produce negative impact");
115	    }
116	
117	    #[test]
118	    fn impact_decays_with_time() {
119	        let mut k = PropagatorKernel::calibrated();
120	        k.push(0, 1.0, 1.0);
121	        let i1s = k.impact(1_000_000_000);
122	        let i10s = k.impact(10_000_000_000);
123	        let i60s = k.impact(60_000_000_000);
124	        assert!(i1s > i10s && i10s > i60s, "impact must decay: {i1s:.1} > {i10s:.1} > {i60s:.1}");
125	    }
126	
127	    #[test]
128	    fn sqrt_law_holds() {
129	        // Impact ∝ √V: doubling volume should increase impact by √2 ≈ 1.41×
130	        let mut k1 = PropagatorKernel::calibrated();
131	        let mut k2 = PropagatorKernel::calibrated();
132	        k1.push(0, 1.0, 1.0);
133	        k2.push(0, 1.0, 2.0);
134	        let i1 = k1.impact(1_000_000_000);
135	        let i2 = k2.impact(1_000_000_000);
136	        let ratio = i2 / i1;
137	        assert!((ratio - std::f64::consts::SQRT_2).abs() < 0.01,
138	            "I(2V)/I(V) should be √2 ≈ 1.414, got {ratio:.4}");
139	    }
140	
141	    #[test]
142	    fn expired_impulses_are_pruned() {
143	        let mut k = PropagatorKernel::calibrated();
144	        k.push(0, 1.0, 1.0);
145	        assert_eq!(k.len(), 1);
146	        // Query far in the future (> 60s cutoff).
147	        let _ = k.impact(100_000_000_000); // 100s later
148	        assert_eq!(k.len(), 0, "impulse older than cutoff should be pruned");
149	    }
150	
151	    #[test]
152	    fn no_impact_without_fills() {
153	        let mut k = PropagatorKernel::calibrated();
154	        assert_eq!(k.impact(1_000_000_000), 0.0);
155	    }
156	
157	    #[test]
158	    fn opposing_fills_cancel() {
159	        let mut k = PropagatorKernel::calibrated();
160	        k.push(0, 1.0, 1.0);  // buy 1 BTC
161	        k.push(0, -1.0, 1.0); // sell 1 BTC at same time
162	        let imp = k.impact(1_000_000_000);
163	        assert!(imp.abs() < 1e-10, "equal opposing fills should cancel, got {imp}");
164	    }
165	}
