//! Feed-event representation, binary-compatible with hftbacktest's `.npz` data
//! so the P1.2 replay harness can stream the exact files Phase 0 produced.
//!
//! Flag constants and the `Event` layout are copied (with simplification) from
//! refs/hftbacktest/hftbacktest/src/types.rs:150-331. The encoding packs the
//! event *kind* in the low byte and side/validity *attribute bits* in the high
//! bits of a single u64.

/// Event kind (low byte of `ev`): aggregate depth change at one price level.
pub const DEPTH_EVENT: u64 = 1;
/// Event kind: a trade print.
pub const TRADE_EVENT: u64 = 2;
/// Event kind: clear the book (or one side of it) up to a price.
pub const DEPTH_CLEAR_EVENT: u64 = 3;
/// Event kind: one level of a full book snapshot.
pub const DEPTH_SNAPSHOT_EVENT: u64 = 4;
/// Event kind: best-bid/offer update (some venues publish a faster BBO feed).
pub const DEPTH_BBO_EVENT: u64 = 5;

/// Attribute bit: bid-side (depth) or buyer-initiated (trade).
pub const BUY_EVENT: u64 = 1 << 29;
/// Attribute bit: ask-side (depth) or seller-initiated (trade).
pub const SELL_EVENT: u64 = 1 << 28;
/// Attribute bit: event is valid for the exchange-side processor (exch_ts).
pub const EXCH_EVENT: u64 = 1 << 31;
/// Attribute bit: event is valid for the local-side processor (local_ts).
pub const LOCAL_EVENT: u64 = 1 << 30;

/// One feed event. Field order, widths, and the 64-byte alignment match
/// hftbacktest's `Event` (types.rs:312-331) so a memory-mapped `.npz` row can be
/// reinterpreted as this struct in P1.2.
#[repr(C, align(64))]
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Event {
    /// Packed kind + attribute flags.
    pub ev: u64,
    /// Timestamp at the exchange (ns).
    pub exch_ts: i64,
    /// Timestamp when our collector received it (ns).
    pub local_ts: i64,
    /// Price.
    pub px: f64,
    /// Quantity (aggregate at level for depth; trade size for trades).
    pub qty: f64,
    /// Order ID (L3 feeds only; zero in our L2 data).
    pub order_id: u64,
    /// Reserved.
    pub ival: i64,
    /// Reserved.
    pub fval: f64,
}

impl Event {
    /// Event kind (low byte).
    #[inline(always)]
    pub fn kind(&self) -> u64 {
        self.ev & 0xff
    }

    #[inline(always)]
    pub fn is_buy(&self) -> bool {
        self.ev & BUY_EVENT != 0
    }

    #[inline(always)]
    pub fn is_sell(&self) -> bool {
        self.ev & SELL_EVENT != 0
    }

    #[inline(always)]
    pub fn is_local(&self) -> bool {
        self.ev & LOCAL_EVENT != 0
    }

    #[inline(always)]
    pub fn is_exch(&self) -> bool {
        self.ev & EXCH_EVENT != 0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn layout_matches_hftbacktest_npz_row() {
        // hftbacktest aligns Event to 64 bytes so rows sit on cache lines; the
        // npz dtype is exactly 64 bytes wide. If this breaks, P1.2's mmap cast breaks.
        assert_eq!(std::mem::size_of::<Event>(), 64);
        assert_eq!(std::mem::align_of::<Event>(), 64);
    }

    #[test]
    fn flag_packing_round_trips() {
        let ev = Event {
            ev: DEPTH_EVENT | BUY_EVENT | LOCAL_EVENT | EXCH_EVENT,
            exch_ts: 1,
            local_ts: 2,
            px: 50_000.1,
            qty: 0.5,
            order_id: 0,
            ival: 0,
            fval: 0.0,
        };
        assert_eq!(ev.kind(), DEPTH_EVENT);
        assert!(ev.is_buy() && !ev.is_sell());
        assert!(ev.is_local() && ev.is_exch());
    }
}

//! Calibrated fill-probability model (P2.5) — the Rust side of P2.2's isotonic fit.
//!
//! P2.2 fitted, from virtual-order labeling on real BTCUSDT L2 data, twelve isotonic
//! curves `P(fill within horizon | queue_frac)` for {bid, ask} × {trade-only,
//! any-decrease} × {1 s, 10 s, 60 s}. `scripts/p25_gen_fill_tables.py` bakes them into
//! `fill_tables.rs`; this module interpolates them into the calibrated replacement for
//! hftbacktest's *uncalibrated* RiskAdverse / Prob queue models (docs/JOURNAL.md
//! Entries 5–6). The sim (P2.5) turns a returned probability into a fill draw.
//!
//! `queue_frac` is the fraction of the resting level volume *ahead* of your order at
//! placement: 0.0 = front of the queue, 1.0 = back. Fill probability is monotone
//! non-increasing in it (isotonic constraint — queue priority has only positive value).

use crate::book::Side;
use crate::fill_tables as t;

/// Which queue-advancement rule the curve was labeled under (docs/JOURNAL.md Entry 6).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FillCriterion {
    /// Queue advances only on trade prints — pessimistic; matches `RiskAdverseQueueModel`.
    Trade,
    /// Queue advances on any level decrease (cancels included) — optimistic bound.
    Any,
}

/// Fill horizon the curve answers for.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Horizon {
    S1,
    S10,
    S60,
}

/// Lookup over the twelve calibrated fill curves. Zero-sized: the tables are `const`.
#[derive(Clone, Copy, Debug, Default)]
pub struct CalibratedFillModel;

impl CalibratedFillModel {
    pub fn new() -> Self {
        Self
    }

    /// `P(fill within horizon | queue_frac)`, linearly interpolated on the 101-point
    /// grid. `queue_frac` is clamped to `[0, 1]`.
    pub fn p_fill(
        &self,
        side: Side,
        crit: FillCriterion,
        horizon: Horizon,
        queue_frac: f64,
    ) -> f64 {
        interp(Self::curve(side, crit, horizon), queue_frac)
    }

    fn curve(side: Side, crit: FillCriterion, horizon: Horizon) -> &'static [f64; t::N] {
        use FillCriterion::{Any, Trade};
        use Horizon::{S1, S10, S60};
        match (side, crit, horizon) {
            (Side::Bid, Trade, S1) => &t::BID_TRADE_1S,
            (Side::Bid, Trade, S10) => &t::BID_TRADE_10S,
            (Side::Bid, Trade, S60) => &t::BID_TRADE_60S,
            (Side::Bid, Any, S1) => &t::BID_ANY_1S,
            (Side::Bid, Any, S10) => &t::BID_ANY_10S,
            (Side::Bid, Any, S60) => &t::BID_ANY_60S,
            (Side::Ask, Trade, S1) => &t::ASK_TRADE_1S,
            (Side::Ask, Trade, S10) => &t::ASK_TRADE_10S,
            (Side::Ask, Trade, S60) => &t::ASK_TRADE_60S,
            (Side::Ask, Any, S1) => &t::ASK_ANY_1S,
            (Side::Ask, Any, S10) => &t::ASK_ANY_10S,
            (Side::Ask, Any, S60) => &t::ASK_ANY_60S,
        }
    }
}

/// Linear interpolation of a 101-point curve sampled on `queue_frac = i * STEP`.
fn interp(curve: &[f64; t::N], q: f64) -> f64 {
    let q = q.clamp(0.0, 1.0);
    let pos = q / t::STEP; // 0.0 ..= 100.0
    let i = pos.floor() as usize;
    if i >= t::N - 1 {
